const handles=[['nw',0,0],['n',50,0],['ne',100,0],['e',100,50],['se',100,100],['s',50,100],['sw',0,100],['w',0,50]];
function selection(){let box=$('selection'),p=mode==='crop'?crop:state.photo;box.hidden=!p;if(!p)return;box.classList.toggle('crop',mode==='crop');Object.assign(box.style,{left:p.x/canvas.width*100+'%',top:p.y/canvas.height*100+'%',width:p.w/canvas.width*100+'%',height:p.h/canvas.height*100+'%'});if(!box.children.length)for(const [name,x,y]of handles){let b=document.createElement('button');b.className='handle';b.dataset.handle=name;b.style.left=x+'%';b.style.top=y+'%';b.style.cursor=({n:'ns',s:'ns',e:'ew',w:'ew',nw:'nwse',se:'nwse',ne:'nesw',sw:'nesw'}[name])+'-resize';b.setAttribute('aria-label',({nw:'왼쪽 위',n:'위',ne:'오른쪽 위',e:'오른쪽',se:'오른쪽 아래',s:'아래',sw:'왼쪽 아래',w:'왼쪽'}[name])+' 테두리');b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const delta=e.shiftKey?20:5,dx=e.key==='ArrowLeft'?-delta:e.key==='ArrowRight'?delta:0,dy=e.key==='ArrowUp'?-delta:e.key==='ArrowDown'?delta:0;snapshot();if(mode==='crop')crop=cropRect(crop,name,dx,dy,state.photo);else Object.assign(state.photo,resizeRect(state.photo,name,dx,dy,$('lock').checked));draw();});box.append(b);}if(mode==='crop'){ctx.save();ctx.fillStyle='#16122466';let p=state.photo;ctx.beginPath();ctx.rect(p.x,p.y,p.w,p.h);ctx.rect(crop.x,crop.y,crop.w,crop.h);ctx.fill('evenodd');ctx.strokeStyle='#ffffff77';ctx.lineWidth=1;for(let i=1;i<3;i++){ctx.beginPath();ctx.moveTo(crop.x+crop.w*i/3,crop.y);ctx.lineTo(crop.x+crop.w*i/3,crop.y+crop.h);ctx.moveTo(crop.x,crop.y+crop.h*i/3);ctx.lineTo(crop.x+crop.w,crop.y+crop.h*i/3);ctx.stroke();}ctx.restore();}}
function setMode(m){mode=m;crop=m==='crop'&&state.photo?pickRect(state.photo):null;$('sizeTab').setAttribute('aria-selected',m==='size');$('cropTab').setAttribute('aria-selected',m==='crop');$('cropActions').hidden=m!=='crop';$('lock').parentElement.hidden=false;$('modeBadge').textContent=m==='crop'?'⌗ 자르기 모드':'↔ 크기 조절 모드';$('modeHelp').textContent=m==='crop'?'테두리 또는 꼭짓점을 안쪽으로 드래그한 뒤 자르기를 적용하세요.':'위·아래는 높이만, 좌·우는 너비만 바뀝니다.';draw();if(!state.photo)notice('사진을 먼저 불러오면 여덟 개의 조절점이 나타납니다.');}
const pickRect=p=>({x:p.x,y:p.y,w:p.w,h:p.h});
function applyCrop(){if(!state.photo||!crop)return false;snapshot();const p=state.photo,r=crop;const sx=p.sx+(r.x-p.x)/p.w*p.sw,sy=p.sy+(r.y-p.y)/p.h*p.sh,sw=r.w/p.w*p.sw,sh=r.h/p.h*p.sh;Object.assign(p,r,{sx,sy,sw,sh});normalizeSurface();setMode('size');notice('자르기를 적용했어요. 이미지 저장으로 내려받으세요.');return true;}
