stage.addEventListener('pointerdown',e=>{const q=point(e),p=state.photo;let handle=e.target.dataset.handle;if(!handle&&p){const r=mode==='crop'?crop:p,tol=12*canvas.width/canvas.getBoundingClientRect().width;if(q.x>=r.x-tol&&q.x<=r.x+r.w+tol&&q.y>=r.y-tol&&q.y<=r.y+r.h+tol){let vertical=Math.abs(q.y-r.y)<tol?'n':Math.abs(q.y-r.y-r.h)<tol?'s':'';let horizontal=Math.abs(q.x-r.x)<tol?'w':Math.abs(q.x-r.x-r.w)<tol?'e':'';handle=vertical+horizontal;}}const kind=handle?'handle':inside(q,textBox)&&state.text?'text':inside(q,p)&&mode==='size'&&!isPhotoSurface()?'move':null;if(!kind)return;e.preventDefault();snapshot();drag={viewport:canvas.getBoundingClientRect(),cw:canvas.width,ch:canvas.height,kind,handle,q,p:p?structuredClone(p):null,crop:crop?{...crop}:null,tx:state.textX,ty:state.textY};stage.setPointerCapture(e.pointerId);});
