function loadImage(src){return new Promise((resolve,reject)=>{const img=new Image;img.onload=()=>resolve(img);img.onerror=()=>reject(Error('이미지 데이터를 읽을 수 없습니다.'));img.src=src;});}
async function cleanImage(file){if(!file||!['image/png','image/jpeg'].includes(file.type))throw Error('PNG 또는 JPEG 파일만 지원합니다. 기존 편집은 유지됩니다.');if(file.size>20*1024*1024)throw Error('20MB 이하의 사진을 선택해 주세요. 기존 편집은 유지됩니다.');let u=URL.createObjectURL(file);try{const img=await loadImage(u);if(img.width*img.height>40000000||img.width>12000||img.height>12000)throw Error('사진이 너무 큽니다. 4천만 화소, 한 변 12000px 이하를 사용해 주세요.');const c=document.createElement('canvas');const scale=Math.min(1,2400/Math.max(img.width,img.height));c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);return await loadImage(c.toDataURL('image/png'));}finally{URL.revokeObjectURL(u);}}
