$('imageFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;const serial=++uploadSerial;try{const img=await cleanImage(file);if(serial!==uploadSerial)return;snapshot();image=img;state.photo={src:img.src,sx:0,sy:0,sw:img.width,sh:img.height,x:0,y:0,w:img.width,h:img.height};fitPhoto();setMode('size');notice('사진을 불러왔어요. 테두리와 꼭짓점을 드래그해 보세요.');}catch(err){notice(err.message,true);}};
$('format').onchange=()=>draw();
function deletePhoto(){
 if(!state.photo)return;
 snapshot();
 ++uploadSerial;
 state.photo=null;
 state.photoCanvas=false;
 image=null;crop=null;drag=null;
 $('imageFile').value='';
 setMode('size');sync();
 notice('사진을 삭제했어요. 되돌리기를 누르면 복구할 수 있습니다.');
}
$('deletePhoto').onclick=deletePhoto;
document.addEventListener('keydown',e=>{
 if(e.key!=='Delete'||e.defaultPrevented||e.isComposing||e.repeat||e.ctrlKey||e.altKey||e.metaKey||e.shiftKey)return;
 const editing=e.composedPath().some(node=>node?.isContentEditable||node?.matches?.('input, textarea, select, [role="textbox"]'));
 if(editing||!state.photo)return;
 e.preventDefault();deletePhoto();
});
$('sizeTab').onclick=()=>setMode('size');$('cropTab').onclick=()=>setMode('crop');$('applyCrop').onclick=()=>applyCrop();$('cancelCrop').onclick=()=>setMode('size');$('fit').onclick=()=>{if(state.photo){snapshot();fitPhoto();}};$('resetImage').onclick=()=>{if(!state.photo)return;snapshot();Object.assign(state.photo,{sx:0,sy:0,sw:image.width,sh:image.height});fitPhoto();notice('원본 영역으로 복구했어요.');};
$('undo').onclick=async()=>{if(!history.length)return;const previous=history[history.length-1];try{const img=previous.photo?await loadImage(previous.photo.src):null;history.pop();state=previous;image=img;setMode('size');sync();notice('이전 편집으로 되돌렸어요.');}catch(e){notice(e.message,true);}};
for(const k of ['background','text','fontSize','textColor','textX','textY']){$(k).addEventListener('focus',()=>snapshot());$(k).oninput=()=>{state[k]=['fontSize','textX','textY'].includes(k)?Number($(k).value):$(k).value;$('fontSizeOut').textContent=state.fontSize;draw();};}
document.querySelectorAll('[data-ratio]').forEach(b=>b.onclick=()=>{snapshot();setCanvasRatio(state,b.dataset.ratio);setMode('size');sync();});
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
$('downloadPhoto').onclick=()=>{if(!state.photo)return notice('먼저 사진을 불러와 주세요.',true);if(mode==='crop')applyCrop();const p=state.photo,out=document.createElement('canvas');out.width=Math.max(1,Math.round(p.w));out.height=Math.max(1,Math.round(p.h));if(out.width*out.height>40000000)return notice('저장할 사진이 너무 큽니다. 크기를 줄여 주세요.',true);const c=out.getContext('2d'),type=$('format').value;if(type==='jpeg'){c.fillStyle=state.background;c.fillRect(0,0,out.width,out.height);}c.drawImage(image,p.sx,p.sy,p.sw,p.sh,0,0,out.width,out.height);out.toBlob(blob=>{if(blob){download(blob,'edited-photo.'+(type==='jpeg'?'jpg':'png'));notice('편집한 사진만 저장했어요.');}else notice('사진을 저장하지 못했습니다.',true);},'image/'+type,.95);};
$('download').onclick=async()=>{if(state.canvasEnabled===false&&!state.photo)return notice('캔버스를 추가하거나 사진을 불러오세요.',true);if(mode==='crop')applyCrop();await document.fonts.ready;const out=document.createElement('canvas');out.width=canvas.width;out.height=canvas.height;if(out.width*out.height>40000000)return notice('저장 영역이 너무 큽니다. 사진 크기를 줄여 주세요.',true);render(out.getContext('2d'),out.width,out.height);const type=$('format').value;if(type==='jpeg'){const c=out.getContext('2d');c.save();c.globalCompositeOperation='destination-over';c.fillStyle=state.background;c.fillRect(0,0,out.width,out.height);c.restore();}out.toBlob(blob=>{if(!blob)return notice('저장에 실패했습니다. 다시 시도해 주세요.',true);download(blob,`moment-${out.width}x${out.height}.${type==='jpeg'?'jpg':'png'}`);notice('완성 이미지를 저장했어요.');},'image/'+type,.95);};
const presets=[{name:'차분한 순간',sub:'MOMENTS TO KEEP',title:'a little moment.',bg:'#e9e4db',color:'#ffffff',design:'quiet',text:'오늘의 작은 순간을\n오래 기억하기',ratio:'1:1'},{name:'나만의 한마디',sub:'YOUR WORDS, YOUR WAY',title:'MAKE IT YOURS.',bg:'#d9e9c2',color:'#334531',design:'bold',text:'지금, 나답게.',ratio:'4:5'},{name:'오늘의 기록',sub:'A NOTE TO MYSELF',title:'Dear, today',bg:'#f1e4d9',color:'#71614f',design:'note',text:'조금 느려도 괜찮아.\n오늘도 한 걸음.',ratio:'9:16'}];
for(const p of presets){const b=document.createElement('button');b.className='preset';b.innerHTML='<div class="preset-art"><small></small><span></span></div><div class="preset-name"><span></span><span>↗</span></div>';b.querySelector('.preset-art').style.background=p.bg;b.querySelector('.preset-art').style.color=p.color;b.querySelector('small').textContent=p.sub;b.querySelector('.preset-art span').textContent=p.title;b.querySelector('.preset-name span').textContent=p.name;b.onclick=()=>{snapshot();Object.assign(state,{background:p.bg,textColor:p.color,design:p.design,text:p.text,ratio:p.ratio,fontSize:64,textX:50,textY:72});setCanvasRatio(state,p.ratio);sync();notice('템플릿을 바꿨어요. 업로드한 사진은 유지됩니다.');};$('presets').append(b);}
const dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('moment-studio-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('templates',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(Error('이 브라우저에서 저장 공간을 열 수 없습니다. JSON으로 백업해 주세요.'));});
async function dbRead(){const db=await dbPromise;return new Promise((resolve,reject)=>{const req=db.transaction('templates').objectStore('templates').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function dbSave(list){const db=await dbPromise;return new Promise((resolve,reject)=>{const tx=db.transaction('templates','readwrite'),s=tx.objectStore('templates');s.clear();for(const t of list)s.put(t);tx.oncomplete=resolve;tx.onerror=tx.onabort=()=>reject(Error('저장 공간이 부족하거나 사용할 수 없습니다. 기존 템플릿은 유지됩니다.'));});}
async function commitTemplates(next){await dbSave(next);templates=next;renderTemplates();}
async function restore(s){if(!validState(s))throw Error('템플릿 내용이 올바르지 않습니다.');const img=s.photo?await loadImage(s.photo.src):null;if(img&&(s.photo.sx+s.photo.sw>img.width+.01||s.photo.sy+s.photo.sh>img.height+.01))throw Error('이미지 자르기 영역이 잘못되었습니다.');snapshot();state={...structuredClone(initial),...structuredClone(s)};image=img;setMode('size');sync();}
function renderTemplates(){$('templateCount').textContent=templates.length;$('templates').replaceChildren();if(!templates.length){const p=document.createElement('p');p.className='muted';p.textContent='나만의 템플릿을 저장해 보세요.';$('templates').append(p);}for(const t of templates){const row=document.createElement('div');row.className='template-row';const name=document.createElement('strong');name.textContent=t.name;row.append(name);for(const [label,action] of [['불러오기',async()=>{await restore(t.state);selected=t.id;$('templateName').value=t.name;notice('저장한 템플릿을 불러왔어요.');}],['현재 편집으로 수정',async()=>{if(!confirm(`“${t.name}”을 현재 편집 내용으로 바꿀까요?`))return;if(mode==='crop')applyCrop();const name=$('templateName').value.trim()||t.name;await commitTemplates(templates.map(x=>x.id===t.id?{...x,name,state:structuredClone(state)}:x));notice('템플릿을 수정했어요.');}],['삭제',async()=>{if(!confirm(`“${t.name}”을 삭제할까요?`))return;await commitTemplates(templates.filter(x=>x.id!==t.id));notice('템플릿을 삭제했어요.');}]]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>action().catch(e=>notice(e.message,true));row.append(b);}$('templates').append(row);}}
$('saveTemplate').onclick=async()=>{const name=$('templateName').value.trim();if(!name)return notice('템플릿 이름을 입력해 주세요.',true);if(templates.length>=100)return notice('최대 100개까지 저장할 수 있습니다.',true);if(mode==='crop')applyCrop();try{await commitTemplates([...templates,{id:crypto.randomUUID(),name,state:structuredClone(state)}]);notice('내 템플릿에 저장했어요. 새로고침 후에도 유지됩니다.');}catch(e){notice(e.message,true);}};
$('exportJSON').onclick=()=>{download(new Blob([JSON.stringify({version:1,templates},null,2)],{type:'application/json'}),'moment-templates.json');notice('템플릿을 JSON으로 백업했어요. 사진도 포함됩니다.');};
$('importJSON').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>50*1024*1024)throw Error('50MB 이하의 JSON만 가져올 수 있습니다.');let bundle;try{bundle=JSON.parse(await file.text());}catch{throw Error('JSON 문법이 손상되어 가져오지 않았습니다. 기존 템플릿은 유지됩니다.');}const imported=validateBundle(bundle);for(const t of imported){if(t.state.photo){const img=await loadImage(t.state.photo.src),p=t.state.photo;if(p.sx+p.sw>img.width+.01||p.sy+p.sh>img.height+.01)throw Error('사진 영역이 올바르지 않습니다.');}}const next=[...templates];for(const t of imported){const i=next.findIndex(x=>x.id===t.id);if(i>=0)next[i]=t;else next.push(t);}if(next.length>100)throw Error('합계 100개를 넘을 수 없습니다.');if(imported.some(t=>templates.some(x=>x.id===t.id))&&!confirm('같은 ID의 템플릿을 백업 내용으로 복원할까요?'))return;await commitTemplates(next);notice(`${imported.length}개 템플릿을 복원했어요.`);}catch(err){notice(err.message+' 기존 편집과 템플릿은 유지됩니다.',true);}};
try{templates=await dbRead();validateBundle({version:1,templates});renderTemplates();}catch(e){notice(e.message,true);}
sync();
if(document.modelContext?.registerTool){const life=new AbortController;try{Promise.resolve(document.modelContext.registerTool({name:'set_card_text',description:'현재 카드의 문구와 글자 크기를 변경합니다.',inputSchema:{type:'object',properties:{text:{type:'string',maxLength:1500},fontSize:{type:'number',minimum:16,maximum:160}},required:['text'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(typeof input?.text!=='string'||input.text.length>1500||input.fontSize!==undefined&&(!Number.isFinite(input.fontSize)||input.fontSize<16||input.fontSize>160))throw Error('Invalid card text');snapshot();state.text=input.text;if(input.fontSize!==undefined)state.fontSize=input.fontSize;sync();return {text:state.text,fontSize:state.fontSize};}},{signal:life.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>life.abort(),{once:true});}
